pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 t2, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        // early deposit sets unlockTime to the (early) current timestamp
        vm.warp(1000);
        vm.deal(actor, amount * 2);
        vm.prank(actor);
        c.Put{value: amount}(0);
        // later deposit with a future unlock time t2 > block.timestamp
        uint256 now2 = block.timestamp + 1;
        t2 = bound(t2, now2, type(uint256).max / 2);
        vm.warp(now2 + 1);
        vm.prank(actor);
        c.Put{value: amount}(t2);
        // rule: after Put(t2) with t2 > block.timestamp, stored unlockTime == t2
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime == t2);
    }
}

