pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor1, address actor2, uint256 t1, uint256 t2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != address(c));
        amount1 = bound(amount1, 1, 10 ether);
        amount2 = bound(amount2, 1, 10 ether);
        t1 = bound(t1, 0, block.timestamp + 365 days);
        t2 = bound(t2, 0, block.timestamp + 365 days);

        vm.deal(actor1, amount1);
        vm.prank(actor1);
        c.Put{value: amount1}(t1);

        vm.deal(actor2, amount2);
        vm.prank(actor2);
        c.Put{value: amount2}(t2);

        // General rule: every successful Put is recorded in the Log, so the
        // second deposit is History entry #1 and its recorded Val equals the
        // second deposit amount. The mutant records nothing on Put, so the
        // entry is missing entirely.
        (, uint256 recVal, , ) = c.History(1);
        assertTrue(recVal == amount2);
    }
}

